with feeders as (
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLID))) as HUB_CLAIM_HK
        , RESERVE_AMT as CURRENT_RESERVE_AMOUNT
        , 'BJAZ_HM_HCM_EXTRACT' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hcm_extract') }}
    where (nullif(trim(CLID),'')) is not null
),

resolved as (
    select
        HUB_CLAIM_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CURRENT_RESERVE_AMOUNT end) as CURRENT_RESERVE_AMOUNT,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_CLAIM_HK
),

hashed as (
    select
        *,
        case when CURRENT_RESERVE_AMOUNT is not null
                     then md5(upper(coalesce(cast(CURRENT_RESERVE_AMOUNT as varchar), '')))
                end as SAT_CLAIM_RESERVE_HASHDIFF
    from resolved
)

select * from hashed
where HUB_CLAIM_HK is not null
  and SAT_CLAIM_RESERVE_HASHDIFF is not null
